/// <summary>
/// REQ-INV-105: makes DYLO_SalesInvoice.Report the default report format of the Customer invoice document.
/// </summary>
class DYLO_PrintMgmtDocType_EventHandler
{
}

Method.Source:
/// <summary>
/// Returns DYLO_SalesInvoice.Report as the default format for sales order invoices.
/// </summary>
/// <param name = "_docType">The print management document type.</param>
/// <param name = "_result">The result that receives the default report format.</param>
[SubscribesTo(classStr(PrintMgmtDocType), delegateStr(PrintMgmtDocType, getDefaultReportFormatDelegate))]
public static void getDefaultReportFormatDelegate(PrintMgmtDocumentType _docType, EventHandlerResult _result)
{
    if (_docType == PrintMgmtDocumentType::SalesOrderInvoice)
    {
        _result.result(ssrsReportStr(DYLO_SalesInvoice, Report));
    }
}
